5158,{achID=1396,awp=30002,e=18,id=17})}}),q(13067,{awp=30008,coords={{57.2,46.6,117}},description="After defeating Skadi, the Elder is underneath the staircase before you enter the Ruined Court.",e=18,isYearly=1,maps={136,137},qgs={30538},g={i(21100,{b=1}),i(21746,{b=1,f=55}),crit(5265,{achID=910,awp=30002,e=18,id=14})}}),q(8727,{coords={{27.66,11.64,23}},description="Enter Stratholme through the main gate.  The Elder is in the northeast corner, east of The Unforgiven.",e=18,isYearly=1,maps=a[535],qgs={15607},g={i(21100,{b=1}),i(21746,{b=1,f=55}),crit(1915,{achID=910,awp=30002,e=18,id=7})}}),q(13021,{awp=30008,coords={{27.5,26,114}},description="When you enter the Nexus, turn right and loop around the Singing Grove.  The Elder is just before you reach Ormorok's platform.",e=18,isYearly=1,maps={129},qgs={30536},g={i(21100,{b=1}),i(21746,{b=1,f=55}),crit(5260,{achID=910,awp=30002,e=18,id=9})}}),q(13017,{awp=30008,coords={{57.9,50,117}},description="After defeating Keleseth, continue through the mining tunnel.  Before heading up the stairs to the next boss, turn left to find the Elder.",e=18,isYearly=1,maps={133,134,135},qgs={30531},g={i(21100,{b=1}),i(21746,{b=1,f=55}),crit(5259,{achID=910,awp=30002,e=18,id=8})}}),q(13023,{awp=30008,coords={{28.5,86.9,121}},description="The Elder is just inside the Raptor Pens, near King Dred.",e=18,isYearly=1,maps={160,161},qgs={30534},g={i(21100,{b=1}),i(21746,{b=1,f=55}),crit(5262,{achID=910,awp=30002,e=18,id=11})}}),q(8619,{coords={{39.06,18.12,35}},description="Located inside Blackrock Depths at the Ring of Law, accessed through the Detention Block. From the entrance walk straight forward across the big central floor into the facing cave, and the Ring of Law can be accessed on the immediate left. \n\nWARNING: Approaching the Elder will also start the encounter, but you can escape the way you came before the gate closes.",e=18,isYearly=1,maps={242},qgs={15549},g={i(21100,{b=1}),i(21746,{b=1,f=55}),crit(1914,{achID=910,awp=30002,e=18,id=6})}}),q(13022,{awp=30008,coords={{26,50.7,115}},description="After defeating Hadronox, jump to the lower level of the dungeon.  The Elder is on the north side of the room where you land.",e=18,isYearly=1,maps={157,158,159},qgs={30533},g={i(21100,{b=1}),i(21746,{b=1,f=55}),crit(5261,{achID=910,awp=30002,e=18,id=10})}}),q(13065,{awp=30008,coords={{76.2,21.1,121}},description="The Elder is on the platform behind the second boss in the dungeon, Drakkari Colossus.",e=18,isYearly=1,maps={153,154},qgs={30537},g={i(21100,{b=1}),i(21746,{b=1,f=55}),crit(5263,{achID=910,awp=30002,e=18,id=12})}}),q(8635,{coords={{44.49,77.14,68}},description="Take the central path to reach the Portal to Inner Maraudon.  Once inside the dungeon, jump down and follow the path to reach the Elder in the far southeast corner of the map.",e=18,isYearly=1,maps={280},qgs={15556},g={i(21100,{b=1}),i(21746,{b=1,f=55}),crit(1912,{achID=910,awp=30002,e=18,id=4})}}),q(8713,{coords={{76.04,45.21,51}},description="Once inside Sunken Temple, turn left.  Elder Starsong is in the small alcove to the northeast.",e=18,isYearly=1,maps={220},qgs={15593},g={i(21100,{b=1}),i(21746,{b=1,f=55}),crit(1911,{achID=910,awp=30002,e=18,id=3})}}),q(8644,{coords={{80.46,40.65,33}},description="Once inside Lower Blackrock Spire, head down and to the left.  The Elder is just past the first bridge.",e=18,isYearly=1,maps=a[418],qgs={15560},g={i(21100,{b=1}),i(21746,{b=1,f=55}),crit(1913,{achID=910,awp=30002,e=18,id=5})}}),q(8676,{coords={{39.21,21.29,71}},description="Inside of Zul'Farrak. Located by the pool where Gahz'rilla is summoned.",e=18,isYearly=1,maps={219},qgs={15578},g={i(21100,{b=1}),i(21746,{b=1,f=55}),crit(1910,{achID=910,awp=30002,e=18,id=2})}}),q(13066,{awp=30008,coords={{39.6,26.9,120}},description="The Elder is on the western side of the Crystalline Quarry inside Halls of Stone.",e=18,isYearly=1,maps={140},qgs={30535},g={i(21100,{b=1}),i(21746,{b=1,f=55}),crit(5264,{achID=910,awp=30002,e=18,id=13})}}),q(8