69132,69134,69078},g={crit(22963,{achID=8069,id=3})}}),e(825,{npcID=67977,g={toy(98132,{awp=50300,b=1,description="Must obtain 250 stacks of Spray Water from the geysers before Tortos."}),crit(22985,{achID=8070,id=1})}}),e(821,{crs={70248,70212,70235,68065,70247},g={crit(22986,{achID=8070,id=2})}}),e(828,{npcID=69712,g={p(1202,{b=1,itemID=94835,npcID=70144,spellID=139148}),crit(22987,{achID=8070,id=3})}}),e(818,{npcID=68036,g={ah(212750,{cost={{"i",211949,1}},description="1. Queue for Halls of Flesh-Shaping LFR at Mogu'Shan Palace in the Vale of Eternal Blossoms. If you can't see the LFR queue NPC, speak to Zidormi outside to change phase.\n2. Kill Durumu and loot Durumus Glass Pupil, then use the item, it doesn't matter where you target the throw.\n3. Wait for the candles around the edge of the platform to spawn in, then head for the purple circle with the cauldrons and the book.\n4. Click the book to get started. :)\n\nYou'll be shown a puzzle that connects some of the candles with coloured beams. You have to count how many beams there are of each colour and click the corresponding cauldron colour that many times.\ne.g 2 candles are connected with 1 beam of green light. Click the green cauldron once.\nYou can keep track of your clicks in your buffs. Once you have the numbers right, click the book to proceed. If you're wrong, the book will knock you over and reset your buffs but will not reset the whole chain of puzzles. You can also right-click off the buff if you overshoot to avoid resetting all of them.\nAs the puzzles progress and get more complicated, the purple cauldron will start giving you more than 1 stack of the purple buff when you click it. This is to help you get to the higher numbers faster. Be careful when you start spam clicking!\n\nTo calculate the higher purple numbers:\nThere are a couple different methods to count them, however the easiest way is using the automatic calculator linked in the WoWhead comments for this item.\n\nThanks to Fiamma from WoWhead for the comment.",type="i",g={o(420873,{cq(79359,{awp=100205,b=1,c=a[957],itemID=212750,lvl=11,spellID=432954})})}}),i(211949,{awp=100205,b=1,c=a[957],f=55,spellID=430921}),crit(22988,{achID=8071,id=1})}}),e(820,{npcID=69017,g={p(1244,{awp=50300,b=1,itemID=97960,npcID=71200,spellID=142029}),crit(22989,{achID=8071,id=2})}}),e(824,{crs={69756,69427},g={p(1183,{b=1,itemID=94152,npcID=69820,spellID=138161}),crit(22990,{achID=8071,id=3})}}),e(817,{crs={68081,68078,68080,68079},g={crit(22991,{achID=8072,id=1})}}),e(829,{crs={68904,68905},g={crit(22965,{achID=8072,id=2})}}),e(832,{npcID=68397,g={i(94867,{b=1}),crit(23317,{achID=8072,id=3})}})}}),d(7,{coords={{83,30.6,390}},crs={80633},g={i(95343,{awp=50004,b=1,description="This item is awarded as a consolation prize to players who did not win loot after defeating a boss encounter in the Raid Finder mode of Throne of Thunder.",modID=1,rwp=80001,sym={{"select","itemID",44984,34535,10360,8491,54436,8485,10394,46398,8496,8486,10392,10822,48114,44970,44973,67282,44974,44982,29960,64403,43698,29953,8492,48116,48118,45002,44980,48120,8487,35504,44721,48124,48126,8495,45606,69992,8490,8488,44965,8499,69991,44971,8489}},u=2,g={s(50452,95972,{awp=50200,b=1,f=6,lvl=35,modID=1}),s(50456,95976,{awp=50200,b=1,f=7,lvl=35,modID=1}),s(50443,95961,{awp=50200,b=1,f=4,lvl=35,modID=1}),s(50455,95975,{awp=50200,b=1,f=7,lvl=35,modID=1}),s(50454,95974,{awp=50200,b=1,f=7,lvl=35,modID=1}),s(50451,95971,{awp=50200,b=1,f=5,lvl=35,modID=1}),s(50444,95962,{awp=50200,b=1,f=4,lvl=35,modID=1}),s(50450,95970,{awp=50200,b=1,f=5,lvl=35,modID=1}),s(50453,95973,{awp=50200,b=1,f=6,lvl=35,modID=1}),s(50458,95979,{awp=50200,b=1,f=7,lvl=35,modID=1}),s(50447,95966,{awp=50200,b=1,f=5,lvl=35,modID=1}),s(50446,95965,{awp=50200,b=1,f=4,lvl=35,modID=1}),s(50457,95978,{awp=50200,b=1,f=7,lvl=35,modID=1}),i(95958,{awp=50200,b=1,f=51,lvl=35,modID=1}),i(95969,{awp=50200,b=1,f=51,lvl=35,modID=1}),i(95980,{awp=50200,b=1,f=51,lvl=35,modID=1}),s(50442,95960,{awp=50200,