{{"i",228983}}})}}),ah(84625,{type="q",g={i(228769,{b=1,spellID=161006}),o(465183,{coords={{42.1,93.4,327},{44.6,90.1,327}},description="Behind Andrestrasz's cave in his cave in Silithus, use Perky Pug or other dog battle pets at the coordinates to dig up the bones.",providers={{"n",37865}},g={i(228772,{b=1,spellID=463196})}}),o(465186,{coords={{37.3,47.7,634}},cost={{"i",228772,1}},description="Use the bones at the Unmarked Grave to receive the crate.",g={i(228770,{b=1,spellID=420213})}}),q(84625,{lvl=10,providers={{"i",228770}}})}}),ah(84909,{type="q",g={i(229369,{b=1,spellID=161006}),o(467489,{coords={{50,73.8,1536}},description="Atop the Seat of the Primus in Maldraxxus, in the back to the right of the portal.",g={i(229367,{b=1,spellID=420213})}}),q(84909,{lvl=10,providers={{"i",229367}}})}})}}),ah(40967,{type="a",g={o(182030,{coords={{44.5,8,78}},description="Inside a rotten tree trunk in the far north of Un'Goro Crater. Use your Torch of Pyrreth to reveal it.",providers={a[6]},g={i(228941,{b=1,spellID=420213})}}),q(84685,{coords={{54.9,28.9,2339}},sourceAchievements={40870},type="hqt"}),q(84684,{coords={{54.9,28.9,2339}},description="Find 3 notes scattered around Azj-Kahet then confront Ratts in Pillar-nest Vosh.",lvl=10,qgs={230042},sourceQuests={84685},g={i(228934,{spellID=462610}),o(466118,{coords={{69.3,93.3,2255}},description="#1. In a cave in Azj'Kahet in the center of 5 Rotglow Settlers.",g={i(228935,{spellID=462610})}}),o(466119,{coords={{31.5,20.8,2213}},description="#2. High up on a ridge overlooking the City of Threads.",g={i(228936,{spellID=462610})}}),o(466120,{coords={{50.7,86.6,2215}},description="#3. Underwater in the center of a lake on the right side of the Azj-Kahet-Hallowfall transition.",g={i(228937,{spellID=462610})}}),o(466128,{coords={{55.1,19,2255},{56.4,17.5,2255}},description="#4. To turn in the quest, enter Pillar-nest Vosh to the left of Faerin's advance, navigate toward the back of the cave then turn around to find a wall you can climb, fall into a tunnel hidden in the wall."}),i(228938,{b=1})}}),i(44124,{b=1,cost={{"i",228938,1},{"i",228941,1}},description="Once reformed, go to the entrance of the Karazhan Catacombs in Deadwind Pass and use your Torch of Pyrreth by the gate to teleport into a secret scenario."}),m(46,{coords={{46.3,69.1,42}},description="Deep into the catacombs the bike is just sitting there out of reach, but is surrounded by 12 basins which can light up with orbs if enough actions are performed.",providers={{"i",44124},a[6]},g={q(84676,{coords={{55,40.2,10},{74.2,37.5,550},{49.2,48,550},{27.3,61.3,1536}},crs={82688,175815},description="Acquire The Light of Their Love buff (spellID 153715) 3 times from visiting areas relevant to Olgra, Mankrik's wife. Stand at these areas with your Torch of Pyrreth until a stack is gained.\n1. The Humble Monument in Northern Barrens.\n2. Young Olgra in Draenor.\n3. Decimator Olgra in Maldraxxus.\n\nFully lights up the 1 O'clock basin.",providers={a[6]},sourceQuests={84684},type="hqt"}),q(84677,{description="Requires the 1 O'clock basin to have been completed to see the obelisk personally.\n1. Acquire the Twitching Eyaball or All-Seeing Eyes toys\n2. Acquire a Perky Pug with either the Dogg-Saron costume from Vashti the Wandering Merchant in Azsuna or the Yipp-Saron costume from Hallow's End (or the AH.)\n3. Bring these items OR find a friend who has them and visit the Ny'Alotha Obelisk above the Seat of Knowledge in the Vale of Eternal Blossoms (BFA).\n4. Have someone summon a perky pug and use the toys, then /pray in front of the obelisk to be granted the Key of Shadows.\n\nThere is a 5-15 minute delay even if you do everything right. Everyone within 10 yards should get the key if anyone in range does it correctly.\n\nFully lights up the 2 O'clock basin",qgs={37865,153297},type="hqt",g={n(153297,{coords={{83.7,27.6,1530}},cost={{"i",116812,1},{"i",229413,1}},providers={{"i",175140},{"i",168123}},g={i(53156,{b=1,description="Opens both doors in the room with the Red Button.",spellID=420213})}})}}),ah(228967,{description="1. Use the Key of Shadows to enter the room to the left of the Red Button. Fish up an Astral key from the bowl on the left bookshelf. Open the Astral chest in the same room, use the goggles.\n2. Interact with any of the consoles around the catacombs until you get a new actionbar. Can't see it? Look in your spellbook for a Number Sequence spell. Click the console again to submit your code.\n3. Enter the codes on adjacent consoles to open each of the chests, each Piece of Hate will give you an orb at the 3 O'clock basin, fully lighting with 9 orbs.",providers={{"i",53156}},sourceQuests=a[941],type="i",g={i(228965,{b=1,sourceQuests=a[941],spellID=3366}),o(466393,{coords={{48.4,79.5,46}},providers={{"i",228965}},sourceQuests=a[941],g={toy(228966,{b=1,sourceQuests=a[941]})}}),o(466400,{coords={{48.9,80.3,46}},description="Code to open at the adjacent decryption console: 88224646",questID=84757,sourceQuests=a[941],g={i(228967,{b=1,sourceQuests=a[941]})}}),o(466413,{coords={{42.9,70.6,46}},description="Code to open at the adjacent decryption console: 17112317",questID=84758,sourceQuests=a[941],g={i(228967,{b=1,sourceQuests=a[941]})}}),o(466479,{coords={{49.5,65.1,46}},description="Code to open at the adjacent decryption console: 1533, 3457, 8265, or 10638",providers={{"i",228966}},questID=84768,sourceQuests=a[941],g={i(228967,{b=1,sourceQuests=a[941]})}}),o(466495,{coords={{67.4,84.3,46}},description="Code to open at the adjacent decryption console: 19019",providers={{"i",228966}},questID=84771,sourceQuests=a[941],g={i(228967,{b=1,sourceQuests=a[941]})}}),o(466484,{coords={{56.3,62.6,46}},description="Code to open at the adjacent decryption console: 5661",providers={{"i",228966}},questID=84769,sourceQuests=a[941],g={i(228967,{b=1,sourceQuests=a[941]})}}),o(466420,{coords={{64.9,48.3,46}},description="Code to open at the adjacent decryption console: 52233",providers={{"i",228966}},questID=84766,sourceQuests=a[941],g={i(228967,{b=1,sourceQuests=a[941]})}}),o(466497,{coords={{70.3,55.4,46}},description="Code to open at the adjacent decryption console: 51567",providers={{"i",228966}},questID=84772,sourceQuests=a[941],g={i(228967,{b=1,sourceQuests=a[941]})}}),o(466489,{coords={{66.3,15.2,46}},description="Code to open at the adjacent decryption console: 115",providers={{"i",228966}},questID=84770,sourceQuests=a[941],g={i(228967,{b=1,sourceQuests=a[941]})}}),ah(84786,{description="In the felcycle room is over a dozen slot machine consoles around the walls, any of them work for this coin. Variations of 777, 888 and 168 are correct answers but the machines only pay out a coin if you are deemed lucky.\nYour luck can be increased by obtaining at least 5 unique lucky things. It's not clear what counts but Blizzard states there are 13 possible lucky sources, some have been listed as a provider for this step. If you see the 'You feel lucky' emote in chat, you should be good, but try at least once anyway, the machine will pay out on first attempt if you're lucky enough, it is not random.\nNo chest will spawn, you will be given the Piece of Hate directly.",providers={{"i",5373},{"i",200265},{"i",198857},{"i",198400},{"i",138382},{"i",138385},{"i",202046}},sourceQuests=a[941],type="q",g={i(228967,{b=1,sourceQuests=a[941]}),q(84786,{sourceQuests=a[941],type="hqt"})}})}}),q(84780,{coords={{52.1,85.1,22}},cost={{"i",228987,1}},description="1. Use the Scroll of Fel Binding sold by Vashti the Wandering Merchant in Azsuna (Broken Isles) right outside Uther's Tomb in the Western Plaugelands.\n2. You will die, return to your corpse and fight the Doomguard while inspecting the four writings on the floor of the tomb. Anyone can summon the demon and writings will stay visible as long as it lives.\n\nFully lights up the 4 O'clock basin.",type="hqt"}),q(84781,{coords={{43.1,41.4,554},{53.3,56.8,555},{39.6,38.4,555}},crs={71876},description="1. Visit the Timeless isle and find Zarhym in the Cavern of Lost Spirits. Talk to Zarhym, a rare ghostly skull inside the entrance to enter the spirit realm.\n2. Within 5 minutes, Navigate to the back of the cave while avoiding ghosts to find Jeremy Feasel. Stay nearby to him, and you will not exit the spirit realm even if your 5 minutes buff expires.\n3. Defeat Jeremy in a pet battle using only 'secret' pets from the list. If someone in your group beats him in a battle, that also counts and he will grant you the quest too on talking to him. The pets MUST be level 25.\n\nFully lights up the 5 O'clock basin.\n\nValid pets:\nBaa'l, Bumbles, Filthy Slime, Francois, Gizmo the Pure, Glimr, Hungering Claw, Jenafur, Lil' Abom, Nelthara, Phoenix Wishwing, Renny, Snowclaw Cub, Spyragos, Sun Darter Hatchling, Taptaf, Terky, Tobias, Wicker Pup",lvl=10,qgs={232048,141941,143730,160704,134406,229779,169514,111984,159783,179008,204367,189117,163897,192343,191381,61087,139770,16445,208643,143189},sourceQuests={84780},g={i(228995,{b=1})}}),q(84811,{description="Use your Torch of Pyrreth at various alters to summon a Spirit of Collections. Perform several actions to appease the spirits on each alter of acquisition, an action may require summoning a mount, pet, or toy associated with each spirit, emoting in some way, or changing your transmog.\n\nSomeone in your phase can appease a spirit for you if nearby, but they must fulfill each part of a spirit's appeasement themselves. If one person covers mount, and another covers pet for example, it will not work.\n\nEach appeased spirit will add an orb to the 6 O'clock basin, and looting the final chest will light it fully.",providers={a[6]},type="hqt",g={q(84809,{coords={{77.1,46.3,50}},crs={230430},description="Confirmed actions to appease:\nMounts: Any with 'blood' in their name\n\nPets: Any with 'blood' in their name\n\nToys: Throbbing Blood Orb",type="hqt"}),q(84807,{coords={{77.5,43.9,50}},crs={230424},description="Confirmed actions to appease:\nOutfit: Cloak of Overwhelming Corruption (or a cloak with the same appearance)\n\nEmotes: /cower with the spirit targeted\n\nMounts: Any with 'corrupted' in their name\n\nPets: Any with 'corrupted' in their name\n\nToys: Ring of Broken Promises, Accursed Tome of the Sargerei",type="hqt"}),q(84810,{coords={{78.1,46.3,50}},crs={230440},description="Confirmed actions to appease:\nOutfit: Cloak of the Black Void (or a cloak with the same appearance)\n\nEmotes: /smirk with the spirit targeted\n\nPets: Lesser Voidcaller, Sir Shady Mrrgglton Junior, Voidwiggler\n\nToys: Shadowy Disguise, Void Totem",type="hqt"}),q(84806,{coords={{78.3,44,50}},crs={230423},description="Confirmed actions to appease:\nOutfit: Any sinstone back cosmetic\n\nPets: Sinheart\n\nToys: Bondable Sinstone",type="hqt"}),q(84808,{coords={{77.1,44.9,50}},crs={230425},description="Confirmed actions to appease:\nOutfit: Be naked\n\nEmotes: /flirt with the spirit targeted\n\nPets: Sister of Temptation\n\nToys: Moroes' Famous Polish, Steamy Romance Novel Kit",type="hqt"}),o(466808,{coords={{78.2,47.7,50}},description="Appears by the wall nearby the Shadow alter once each spirit has been appeased. Use your goggles to see it.",providers={{"i",228966}},sourceQuests={84781,84806,84807,84808,84809,84810},g={i(229007,{b=1,spellID=444913})}})}}),q(84823,{description="Empower your owl pet with the Owl statues in Azsuna then enter the Vault of the Wardens to find a Sentry Statue. Use it to solve a puzzle to receive the mirror.\n\nEmpowering your owl will add 4 orbs to the 7 O'clock basin, and solving the sentry puzzle will light it fully.",maps={630,710,711,712},type="hqt",g={ah(254262,{coords={{44.18,72.41,630},{40.54,73.15,630},{40.52,75.19,630},{37.1,82.16,630},{43.24,85.3,630},{43.66,87.51,630},{50.45,91.67,630},{47.48,84.74,630},{45.97,84.06,630}},description="On the Isle of the Watchers in Azsuna are 9 Owl of the Watchers statues, on any shard, only 4 of them will be interactable at any given time.\n\nYou need an owl pet, the Fledgling Warden Owl sold by the Wardens quartermaster on the same island is confirmed to work, but other owls may work too.\n\nSummon your owl and don't let it disappear by flying too far away. Find an interactable statue and sit in the aura it creates with your pet until an audible sound cue plays and a secret magnifying glass icon appears over your head. Do that again for 4 different statue auras, Red, Green, Blue and Purple.\nYou'll know you're done when your owl has a distinct white orb above their head. Unlocks 4 orbs at Basin 7.",providers={{"n",97128}},type="o",g={q(39353,{description="Unlocks an orb at the 7 O'clock basin.",type="hqt"}),q(26741,{description="Unlocks an orb at the 7 O'clock basin.",lvl=10,type="hqt"}),q(40721,{description="Unlocks an orb at the 7 O'clock basin.",type="hqt"}),q(26704,{description="Unlocks an orb at the 7 O'clock basin.",lvl=10,type="hqt"})}}),o(466943,{description="You must first have completed the previous steps with the watcher statues and empowering your owl.\n1. Clear Vault of the Wardens (any difficulty) with your owl pet summoned through to last boss.\n2. Pick up Elune's light from a statue in the corner of Cordana's arena and QUICKLY get back up to the first boss's room.\n3. Backtrack from the first boss room towards the dungeon entrance, enter the newly opened door on your right, the statue will sit in the center.",maps=a[887],providers={{"n",97128}},g={i(229046,{b=1,description="Place in the center platform before the last set of stairs leading to Glazer's platform in the Vault of Mirrors.",spellID=464277})}}),q(84916,{description="Place in the center platform before the last set of stairs leading to Glazer's platform in the Vault of Mirrors.",maps=a[887],type="hqt"}),o(466960,{crs={109300},description="Once you place the Sentry Statue in the Vault of Mirrors, a 5x5 grid of watcher statues will appear. You need to make each statue descend into the floor, but each statue you click will toggle the state of 4 other statues.\n\nThere are addons and website tools to solve this, for your sanity, use one. You may solve this secret in a group.\n\nFully lights up the 7 O'clock basin.",maps=a[887],providers={{"n",97128},a[6]},g={i(229054,{b=1})}})}}),o(466975,{coords={{59.9,42.6,46}},description="On the left side of the hallway after the second stairwell.",g={q(84829,{cost={{"i",229007,1}},sourceQuests={84811},type="hqt"}),q(84830,{cost={{"i",229054,1}},sourceQuests={84823},type="hqt"}),q(84837,{description="1. Hit begin on the console, then hit submit. A randomized number of rats will spawn in the catacombs.\n2. Count the number of Rats in the whole catacombs, use a targeting macro to make sure you don't miss one. There will also be Catacombs Rats, those DO NOT COUNT. Kill both types of rats once you are sure of your count so they cannot interfere with pressure plates.\n3. Depending on the number of rats, you need to drag a certain number of statues to a specific pressure plate and stack them, the beacon color will shift from Blue->Green->Yellow->Orange->Purple as a plate has 1->2->3->4->5 entities stack on it.\n4. Head back to the Enigma Machine and submit, you will be electrocuted if you get it wrong, leave and reset the instance if you do, restarting at lock 1. Otherwise, continue counting the next set of rats and submitting results using info from the next column until you've completed all 7 locks.\n\nPlate 1 is at 71.6, 20.1 at the top of the map in the felcycle room\nPlate 2 is at 68.5, 34.2 right at the entrance to the felcycle room\nPlate 3 is at 73.6, 43.0 behind the locked gate on the right of the map, use your Relic of Crystal Connections to teleport to the humming crystal in the room by targeting it\nPlate 4 is at 68.8, 50.9 in the center of the hallway opposite the felcycle room\nPlate 5 is at 73.6, 65.3 in the flooded dead end hallway right as you enter the catacombs\nPlate 6 is at 60.2, 71.6 on the left side of the hallway before the cat room\nPlate 7 is at 47.8, 78.9 in the corner of the room with the Astral chest\n\n[# Rats | Lock 1| Lock 2| Lock 3|\n[1 Rats | 1 > P1 | 1 > P2 | 1 > P3 |\n[2 Rats | 1 > P2 | 1 > P4 | 1 > P6 |\n[3 Rats | 1 > P3 | 1 > P6 | 2 > P2 |\n[4 Rats | 1 > P4 | 2 > P1 | 2 > P5 |\n[5 Rats | 1 > P5 | 2 > P3 | 3 > P1 |\n[6 Rats | 1 > P6 | 2 > P3 | 3 > P4 |\n[7 Rats | 1 > P7 | 2 > P7 | 1 > P1 |\n[8 Rats | 2 > P1 | 3 > P2 | 1 > P4 |\n[9 Rats | 2 > P2 | 3 > P4 | 1 > P7 |\n[10Rats| 2 > P3 | 3 > P6 | 2 > P3 |\nExample: Counting 2 rats during Lock 2, stack 1 statue on pressure plate 4.\n\nFully lights up the 8 O'clock basin.",providers={{"i",228996}},sourceQuests={84829,84830},type="hqt",g={n(230653,{coords={{70.6,34.5,46}},description="Right of the entrance of the felcycle room."}),n(230654,{coords={{61.2,47.9,46}},description="Opposite the Enigma Machine."}),n(230655,{coords={{43.4,64.9,46}},description="On the right inside the room ahead of the Red Button."}),n(230652,{coords={{49.3,75.9,46}},description="In the room with the Astral Chest, left of the Red Button."}),n(230657,{coords={{70.3,79.1,46}},description="At the bottom of the entrance stairwell."}),n(230596,{description="This is a |cff4caf50VALID|r rat, it counts!"}),n(230599,{description="This is an |cffff0000INVALID|r rat, it DOESN'T count!"})}})}}),o(467191,{coords={{55.1,19,2255},{56.4,17.5,2255},{56.1,17.9,2255}},description="Return to Pillar-nest Vosh to the left of Faerin's advance, navigate toward the back of the cave then turn around to find a wall you can climb, fall into a tunnel hidden in the wall.\n\nUse your Starry-Eyed goggles to reveal a translucent platform, use your Relic of Crystal Connections on the humming crystal to get up to it.\n\nCode to open at the adjacent decryption console: 84847078.\n\nFully lights the 9 O'clock Basin.",providers={{"i",228966},{"i",228996}},questID=84854,sourceQuests={84837},g={mnt(428013,{b=1,itemID=229348,lvl=10}),ach(40967)}}),n(230070,{coords={{47.4,68.3,46}},description="Interacting with the button starts a 20 second timer, refreshing on clicking again. The orb to the left of the button reports how many times the button has been clicked within that window.",g={q(84702,{description="Unlocks an orb at the 10 O'clock basin.",type="hqt"}),q(84703,{description="Unlocks an orb at the 10 O'clock basin.",type="hqt"})}}),o(475116,{coords={{70.1,90.3,46},{70.3,81,46},{70.5,61.7,46},{56.3,73.3,46},{70.9,53.9,46},{47,78.1,46}},description="These pebbles can be found throughout the catacombs.\n1. Halfway down the entrance stairwell, behind a candelabra sitting on the bannister.\n2. Behind the frame of the archway halfway down the entrance stairwell, opposite the skeleton sitting on the other side of the arch.\n3. To the left of the tilted Replica Owl of the Watchers in the first room after the entrance stairs.\n4. On the inside corner of the doorway to the cat room, interactable through the gate.\n5. In the hand of a skeleton in the corner of the hallway leading to the Felcycle.\n6. On a shelf in the back in the Nature statue room."}),i(228953)}})}})}}),ah(156798,{description="Below is a detailed explanation on how to obtain The Hivemind mount.\n\n***This secret requires you to have debug mode enabled to see the steps. To enable debug mode right click the ATT icon on the minimap, navigate to the general tab and check the \"|Cff15abffDebug Mode|r |cFFFFFFFF(Show Everything)|r\" box.***",displayID=88835,modelScale=1.1,type="i",g={o(13000000,{coords={{65.6,69.3,594}},description="|cFFFFFFFFSTEP 1:|r Purchase |cFFFFD700Talisman of True Treasure Tracking|r. This can be bought from |cFFFFD700Griftah|r in |cFFFFD700Shattrath City|r at |cFFFFFFFF65.6, 69.3|r for 35g\n",g={i(27944,{f=51,spellID=260928})}}),o(13000001,{description="|cFFFFFFFFSTEP 2:|r You must wear the talisman to see/interact with many objects in this secret."}),o(13000032,{description="|cFFFFFFFFSTEP 3:|r Hivemind requires a five-man group.  Four members must each collect a different monocle before the group can continue with the secret.",g={q(50181,{description="Obtaining this monocle requires reading many letters spread around Azeroth.\n\n***You need to interact with all letters in the order listed to progress through the puzzle!***\n",icon=133146,sourceQuests={50187},type="hqt",g={o(280815,{coords={{65.6,69.3,111}},description="|cFFFFFFFFLetter 1:|r The start of this puzzle is the |cFFFFD700Letter from Ms. Graham|r with a blue aura behind |cFFFFD700Griftah|r, which can be interacted with. Click it. The letter reads...\r\r|cFFFFFFFFThe key Factor in successul Wasp Ignition is a solid Ad campaign.|r\n",model="1661948",questID=40397}),o(280836,{coords={{57.4,27.9,650}},description="|cFFFFFFFFLetter 2:|r Go to |cFFFFFFFF57.4, 27.9|r in |cFFFFD700Highmountain|r. The |cFFFFD700Letter from Ms. Graham|r is located in one of the tents on the box next to the pumpkin. Click it. The letter reads...\n\n|cFFFFFFFFOf all of Gai's cures for Nature, the most liberating is Death.|r\n",model="1661948",questID=40314,sourceQuests={40397}}),o(280837,{coords={{47.4,75,47}},description="|cFFFFFFFFLetter 3:|r Go to |cFFFFD700Karazhan (Old)|r in |cFFFFD700Duskwood|r. The third letter is located in |cFFFFD700Medivh's Chambers|r, located after the Chess Event, in the staircase leading to Prince Malchezaar. The letter is on the chair Medivh used to write his scrolls and spells, literally the seat of the guardian. Click it. The letter reads...\n\n|cFFFFFFFFI sat Dumbfounded, watching As the most Subtle Rat reached for the cheese a third time in under an hour.|r\n",model="1661948",questID=40404,sourceQuests={40314}}),o(280838,{coords={{45.7,24,64}},description="|cFFFFFFFFLetter 4:|r Go to |cFFFFD700Razorfen Downs|r in |cFFFFD700Thousand Needles|r. The next |cFFFFD700Letter from Ms. Graham|r is located on a hay box behind the second-to-last boss, |cFFFFD700Death Speaker Blackthorn|r. will spawn on the table.  Click it.  The note reads...\r\r|cFFFFFFFFMs. Sin will accompany you down The longest Streets Of the underworld.|r\n",model="1661948",questID=40252,sourceQuests={40404}}),o(280842,{coords={{44.3,47.3,198}},description="|cFFFFFFFFLetter 5:|r Go to |cFFFFFFFF44.3, 47.3|r in |cFFFFD700Mount Hyjal|r. The next |cFFFFD700Letter from Ms. Graham|r is on a table at the highest floor of the tree that serves as her shrine. Click it.  The note reads...\r\r|cFFFFFFFFThe Elite champions will rule the World with the mightiest F.C.|r\n",model="1661948",questID=40293,sourceQuests={40252}}),o(280843,{coords={{70.8,73.3,118}},description="|cFFFFFFFFLetter 6:|r Go to |cFFFFFFFF70.8, 73.3|r in |cFFFFD700Icecrown|r. The next |cFFFFD700Letter from Ms. Graham|r is on top of a spike at the dam. Click it. The note reads...\r\r|cFFFFFFFFRe: Codex of mastering Sine waves.|r\n",model="1661948",questID=40288,sourceQuests={40293}}),o(280844,{coords={{37.7,63,388}},description="|cFFFFFFFFLetter 7:|r Go to |cFFFFFFFF37.7, 63.0|r in |cFFFFD700Townlong Steppes|r. The final |cFFFFD700Letter from Ms. Graham|r is located near a bell on the back part of the temple. Click it. The note reads...\r\r|cFFFFFFFFMice look so sad when they have a Cleft lip.\n\nHoping you succeed,\n~Ana|r\n",model="1661948",questID=50187,sourceQuests={40288}}),o(280845,{coords={{27.6,27.1,114}},description="|cFFFFFFFFThe Gift:|r Go to |cFFFFFFFF27.6, 27.1|r in |cFFFFD700Coldarra, Borean Tundra|r. The |cFFFFFFFFBlue Crystal Monocle|r is in a container on the highest Nexus ring.\n",questID=50181,sourceQuests={50187},type="hqt",g={s(93108,156724,{b=1,f=2,spellID=260931})}})}}),q(50185,{coords={{35.3,33.6,542}},description="Go to |cFFFFD700Skyreach|r in |cFFFFD700Spires of Arak|r. Behind the final boss of the instance, |cFFFFD700High Sage Viryx|r, you will find a console that you are able to interact with. Use the four glowing yellow balls to move the sun across the board (the north ball, for instance, makes the sun move up).\n\nThe directions and order in which you must move the sun are:\n\n|cFFFFFFFFRight -> Up -> Down -> Up -> Right -> Right -> Up -> Left -> Down -> Up -> Left -> Down|r\n\nLoot the chest that spawns to obtain the |cFFFFFFFFGreen Crystal Monocle|r\n",icon=133146,type="hqt",g={o(280883,{questID=50185,type="hqt",g={s(93111,156727,{b=1,f=2,spellID=260933})}})}}),o(13000031,{description="Fish NPCs across Vashj'ir sell sea-themed currencies which need to be exchanged between the various NPCs in order to obtain the currencies required to purchase the |cFFFFD700Red Crystal Monocle|r.\n\nThe currencies expire after a period of time so it is advised that you purchase the items in the order listed.\n",g={o(13000002,{description="Exchange the following items with the NPC until you receive 5 |cFFFFD700Scintillating Murloc Skin Lotion|r.\n",g={o(13000003,{description="Exchange the following items with the NPC until you receive 50 |cFFFFD700Glittergill Glitter|r.\n",g={o(13000004,{coords={{44.6,20.2,205}},description="|cFFFFFFFFStep 1:|r Purchase 500 |cFFFFD700Seashell|r from |cFFFFD700Sir Finley Mrrgglton|r at |cFFFFFFFF44.6, 20.2|r in |cFFFFD700Shimmering Expanse|r, Vashj'ir.\nThe NPC is at surface level on one of the islets, atop a watchtower.\n"}),o(13000005,{coords={{39.9,77.6,204}},description="|cFFFFFFFFStep 2:|r Purchase 100 |cFFFFD700Cavity-Free Great Shark Tooth|r from |cFFFFD700Volatile Violetscale|r at |cFFFFFFFF39.9, 77.6|r in |cFFFFD700Abyssal Depths|r, Vashj'ir.\nThe NPC is swimming around near the sea floor of the Underlight Canyon.\n"}),o(13000006,{coords={{54.3,24.5,205}},description="|cFFFFFFFFStep 3:|r Purchase 50 |cFFFFD700Razoreel Larva|r from |cFFFFD700Manta Stargazer|r at |cFFFFFFFF54.3, 24.5|r in |cFFFFD700Shimmering Expanse|r, Vashj'ir.\nThe NPC is near the surface, hovering around Shimmering Grotto.\n"}),o(13000007,{coords={{69,47.8,205}},description="|cFFFFFFFFStep 4:|r Purchase 250 |cFFFFD700Well Fed Doctor Fish|r from |cFFFFD700Lil' Whaley|r at |cFFFFFFFF69.0, 47.86|r in |cFFFFD700Shimmering Expanse|r, Vashj'ir.\nThe NPC is close to the sea floor, next to the Ruins of Thelse