ords={{36.2,36.2,35},{40.6,37.8,35},{37,28.2,35}},g={r(18422,{b=1,itemID=14486,learnedAt=290,requireSkill=197})}}),n(9046,{description="This used to be a simple Rare Creature with a limited loot table. He was later repurposed for use with the BWL Attunement Quest Chain. The two items listed below were never available in WoW Classic.",g={s(4813,13254,{awp=100107,b=1,f=8,lvl=22}),s(4809,13248,{awp=100107,b=1,f=31,lvl=23}),i(18987,{b=1,lvl=17,rwp=60003,u=2})}}),n(8924,{coords={{37.8,61.3,35},{47.6,62,35}},g={i(19259,{spellID=23678}),s(4194,11603,{f=34,lvl=22})}})})}}),m(17,{crs={88206},icon=236720,lore="The Blasted Lands bear that name for a reason: they were twisted by the magic that brought the Dark Portal into being, spewing the rampaging Horde into Azeroth.\n\nThis wasted desert of red clay is home to the original Dark Portal. The portal still stands, and leads to Outland — the remains of the orcs' sundered homeworld, Draenor. Nethergarde Keep, a Stormwind fortress of dour mages and paladins, keeps watch over the portal and the demons and ogres that would abuse its power.\n\nNow, the wretched land hosts few inhabitants and no significant settlements. Magic that leaked through the Dark Portal warped the Blasted Lands, leaving an infertile desert landscape. Hardy desert species like Basilisks, Scorpions and Hyenas have since colonized the area. The red rocks of the region do not come by their color naturally. The original tan color was transmuted into the unearthly crimson by searing heat and chaotic energies when the Dark Portal was destroyed.",petBattleLvl=16,lvl=15,g={h(-12,{ach(4909,{awp=40003,g={crit(15206,{achID=1676,awp=30002,id=1})}}),ach(766,{awp=30002,g={crit(1280,{achID=42,id=5})}})}),flt(101,{awp=50004,pb=1,sym={{"select","speciesID",635,415,414,412}},g={p(416,{coords={{59.6,60.8,17}},npcID=61329,pb=1,g={crit(21623,{achID=6586,id=62,pb=1})}})}}),h(-30,{awp=30002,g={exp(1441,{crit(1033,{achID=766,id=7})}),exp(1437,{crit(1028,{achID=766,id=2})}),exp(1439,{c