n(43372),n(43503)}})}),h(-46,{n(50062,{coords={{55.05,54.11,207},{53.72,39.71,207},{49.12,55.6,207},{43,50.79,207},{50.5,63.5,207},{42,43.6,207}},description="Aeonaxx has six possible spawn points. It shares these spawn points and its spawn timer with a bat called Blood Seeker. This means that only one of the NPCs (Aeonaxx or Blood Seeker) can be up on a realm at any given time. Once Aeonaxx spawns, he will fly in a small circle near his spawn point, and will continue to do so until killed or until a server reset. In contrast, when Blood Seeker spawns, it only stays up for about 15 seconds before despawning.\n\nBlood Seeker does not drop a mount, and spawns much more frequently than Aeonaxx. Blood Seeker quickly becomes a nuisance to any lucky enough to see him in his 15-second spawn window, but finding him can be helpful. Tracking Blood Seeker's spawns will help you keep track of when it is possible for Aeonaxx to spawn. Whenever you are able to spot this bat, it means that you can safely take a break from your camping for 2 hours, as there will not be a spawn until the minimum timer has passed (2 hours). Aeonaxx is often thought of as \"the rare spawn of Blood Seeker.\" Simply put, this means that there is a small chance for Aeonaxx to spawn instead of Blood Seeker whenever a spawn is due.",g={mnt(88718,{b=1,itemID=63042,lvl=27})}}),n(50059,{coords={{32.8,76.4,207},{37.6,81.6,207},{43.6,87.8,207},{45.8,84.2,207}},g={s(34269,67237,{f=4,lvl=31})}}),n(49822,{coords={{61.2,22.6,207}},description="Found inside Crumbling Depths, requires the daily quest Underground Economy. Use the bomb \"Ricket's Tickers\" in the central cavern to reach the cave where Jadefang spawns.",g={p(279,{b=1,itemID=64494,npcID=48982,spellID=91343})}}),n(50060,{coords={{55,25.6,207}},g={s(34270,67238,{f=7,lvl=31})}})}),h(-58,{n(45408,{coords={{56.8,13.2,207}},g={s(33279,65907,{b=1,f=9,minReputation={1171,3000},spellID=57818}),i(62342,{b=1,f=55,lvl=32,minReputation={1171,9000},spellID=86898}),i(6