thin the city of Zuldazar. Should the trolls shatter this seal, G'huun will be freed from its eons-long confinement to rule the world. Upon arriving in Nazmir, you will meet Princess Talanji, who will ask you to escort her as you look for signs of blood troll activity in the area.",petBattleLvl=25,lvl=20,g={h(-12,{ach(12942,{crit(71377,{achID=41203,awp=110007,id=1})}),ach(41203,{awp=110007,g={crit(71271,{achID=40956,id=3})}}),ach(13024,{crit(71379,{achID=41203,awp=110007,id=3})}),ach(12588,{crit(40542,{achID=12588,coords={{30.3,52.7,863},{30.1,39.7,863},{47.5,35.1,863}},icon=459041,id=1,providers={{"o",291233}}}),crit(40543,{achID=12588,coords={{55.6,74.7,863},{46.1,71.9,863}},icon=1785788,id=2,providers={{"o",291238}}}),crit(40544,{achID=12588,coords={{28,35.3,863},{35.2,66.4,863},{48.7,74.9,863}},icon=134187,id=3,providers={{"o",291241}}}),crit(40546,{achID=12588,coords={{73.7,39.7,863},{81.9,55.9,863}},icon=959805,id=4,providers={{"o",292812}}}),crit(40549,{achID=12588,coords={{52.6,35.8,863},{50.4,39.7,863}},icon=960694,id=5,providers={{"o",292823}}}),crit(40550,{achID=12588,coords={{54.5,56.1,863},{55.4,67.1,863},{76.3,61,863},{49.4,48.9,863},{51.8,24.3,863}},icon=134439,id=6,providers={{"o",292825}}}),crit(71381,{achID=41203,awp=110007,id=5})}),ach(12561,{crit(41302,{achID=12988,id=5})}),ach(13028,{crs={143317},g={q(53417,{coords={{69.5,58.6,863}},type="hqt"}),q(53418,{coords={{65.5,50.9,863}},type="hqt"}),q(53419,{coords={{56,65,863}},type="hqt"}),q(53421,{coords={{33.4,61.5,863}},type="hqt"}),q(53420,{coords={{52.8,42.8,863}},type="hqt"}),q(53422,{coords={{44.6,92.7,863}},type="hqt"}),q(53423,{coords={{28.8,83.1,863}},type="hqt"}),q(53424,{coords={{24.1,91.7,863}},type="hqt"}),q(53425,{coords={{21.8,69.3,863}},type="hqt"}),q(53426,{coords={{25.6,40.5,863}},type="hqt"}),crit(71382,{achID=41203,awp=110007,id=6})}}),ach(12948,{r=1}),ach(11868,{r=1,g={crit(40031,{achID=13294,id=2}),crit(40031,{achID=12479,id=2})}}),ach(13263,{r=1,sourceQuests={53782},g={crit(713