161441},isDaily=1,questID=58526,g={s(112273,179487,{b=1,f=35,lvl=48}),crit(50617,{achID=14307,id=26})}}),n(170899,{coords={{53.5,88.3,1533},{33.3,59.7,1533},{71.8,38.8,1533},{64.3,69.8,1533},{39.1,20.4,1533},{32.1,17.8,1533}},crs={170835,170836,170832,170834,170833},description="You have to ring all 5 vespers within 5 minutes to summon the Ascended Council at |cFFFFFFFF53.5, 88.3|r.  The vespers are spread out all over the map, so this might require at least a couple people.",isDaily=1,questID=60933,g={o(354175,{coords={{53.5,88.7,1533}},isDaily=1,questID=60977,g={mnt(342335,{b=1,itemID=183741})}}),crit(50619,{achID=14307,id=29})}}),n(171211,{coords={{32.6,23.4,1533}},description="Fragile Humility Scrolls can be found throughout the Court of Elation.  They are floating unfurled scrolls that do not sparkle, but glow purple.  After you find one, read it to Eolis to start the encounter.\n\nOnly available to level 60 characters, both spawning and looting.",isDaily=1,questID=61083,g={s(114849,183607,{b=1,f=29,lvl=48}),i(180613,{spellID=334036}),crit(50613,{achID=14307,id=22})}}),n(160629,{coords={{51.2,40.6,1533}},crs={161536},description="To start the encounter, find casks full of Fermenting Purian Fruit near the rare and bring them to Baedos' Fruit Barrel.",isDaily=1,questID=58648,g={crit(50592,{achID=14307,id=6})}}),n(170659,{coords={{48.4,50.4,1533}},isDaily=1,questID=60897,g={i(180704,{b=1,f=55,spellID=334833}),crit(50602,{achID=14307,id=11})}}),n(171189,{coords={{57.2,62.4,1533}},isDaily=1,questID=59022,g={i(182682,{b=1,f=53,lvl=48,spellID=339979}),crit(50612,{achID=14307,id=21})}}),n(170932,{coords={{50.6,59.6,1533}},description="If the rare is not attackable, you can kill Anima-Starved Cloudfeathers in the area to provoke it.",isDaily=1,questID=60978,g={p(2925,{b=1,itemID=180812,npcID=171565,spellID=334789}),crit(50604,{achID=14307,id=13})}}),n(161530,{coords={{55.3,80.3,1533}},crs={161441},isDaily=1,questID=60571,g={s(112274,179488,{b=1,f=34,lvl=48}),crit(50598,{achID=14307,id=4})}}),n(171014,{coords={{66,43.6,1533}},crs={157979},description="First, read the 6 chapters of Mercia's Legacy in order.\n\nChapter One - |cFFFFFFFF66.1, 44.1|r, on a small table with two vases.\nChapter Two - |cFFFFFFFF65.9, 44.1|r, on a bench.\nChapter Three - |cFFFFFFFF65.7, 43.9|r, behind a bench.\nChapter Four - |cFFFFFFFF65.7, 43.4|r, on the lower-left shelf.\nChapter Five - |cFFFFFFFF65.9, 43.2|r, to the right of the bench.\nChapter Six - |cFFFFFFFF66.2, 43.2|r, on the lower-right corner of the table.\n\nSpeak to the Echo of Mercia, and she will give you a 5-minute buff allowing you to find the secret 7th chapter of the story.  It will be outside the main temple room; just look at all the tables until you find a glowing purple scroll.\n\nPick up the 7th chapter scroll, bring it to the Echo of Mercia, and the rare will appear.",isDaily=1,providers={{"o",354283},{"o",354284},{"o",354285},{"o",354286},{"o",354287},{"o",354288},{"i",180569}},questID=61002,g={s(114848,183606,{b=1,f=8,lvl=48}),i(184295,{b=1,f=51,lvl=48}),s(114850,183608,{b=1,f=1,lvl=48}),s(114856,183614,{b=1,f=23,lvl=48}),s(114853,183611,{b=1,f=26,lvl=48}),s(114846,183604,{b=1,f=33,lvl=48}),o(354467,{coords={{65.3,44.4,1533},{65.4,42.9,1533},{65.8,44.4,1533},{66.4,43,1533},{67.3,43.6,1533},{67.4,42.8,1533}},g={i(180569)}}),s(114855,183613,{b=1,f=20,lvl=48}),s(114854,183612,{b=1,f=23,lvl=48}),s(114851,183609,{b=1,f=34,lvl=48}),s(114849,183607,{b=1,f=29,lvl=48}),s(114847,183605,{b=1,f=35,lvl=48}),s(114852,183610,{b=1,f=20,lvl=48}),crit(50610,{achID=14307,id=19})}}),n(171010,{coords={{56.4,46.1,1533}},crs={171300},description="To start the encounter, you need to find a Discarded Phalynx Core and use it on the Malfunctioning Clawguard.",isDaily=1,questID=60999,g={i(182759,{b=1}),i(180651),crit(50615,{achID=14307,id=24})}}),n(170623,{coords={{27.8,30,1533}},description="If the rare is up, you will get a debuff called Ominous Gaze when you are close to it.  To start the encounter, you need to die and speak to the NPC.",isDaily=1,questID=60883,g={s(115605,184297,{b=1,f=26,lvl=48}),crit(50603,{achID=14307,id=12})}}),n(171011,{coords={{37,41.8,1533}},description="As soon as Demi is pulled, she will start running east.  She will pull additional Forsworn mobs for you to contend with, and she has 100 stacks of a buff that causes her to take reduced damage.  The stacks drop each time she is attacked, so she will take progressively more damage.  Upon defeat, she drops the treasure she is holding.\n\nThis rare is soloable, but having decent gear and at least one more person may be helpful — if Demi makes it to safety, she will despawn.",isDaily=1,questID=61000,g={o(354649,{s(114848,183606,{b=1,f=8,lvl=48}),s(114850,183608,{b=1,f=1,lvl=48}),s(114856,183614,{b=1,f=23,lvl=48}),s(114855,183613,{b=1,f=20,lvl=48}),s(114853,183611,{b=1,f=26,lvl=48}),s(114854,183612,{b=1,f=23,lvl=48}),s(114846,183604,{b=1,f=33,lvl=48}),s(114851,183609,{b=1,f=34,lvl=48}),s(114849,183607,{b=1,f=29,lvl=48}),s(114852,183610,{b=1,f=20,lvl=48}),s(114847,183605,{b=1,f=35,lvl=48})}),crit(50611,{achID=14307,id=20,questID=61069})}}),n(163460,{coords={{40.9,47.4,1533}},description="Stewart offers you his Stewpendous Stew in thanks after you save him from Dionae.",isDaily=1,questID=62650,g={o(344588,{p(2932,{b=1,itemID=180856,npcID=171693,spellID=335050})}),crit(50595,{achID=14307,id=9})}}),n(171255,{coords={{46.8,64,1533}},isDaily=1,questID=61091,g={i(180062,{b=1,spellID=344912}),crit(50614,{achID=14307,id=23,questID=61082})}}),n(171009,{coords={{50.8,19.6,1533}},description="Force the rare to spawn by killing mobs around the Eternal Forge.  Forge-Keeper Mnemis will periodically announce the threat level, and Aegeon will be dispatched when the threat level reaches Major.",isDaily=1,questID=60998,g={toy(184404,{b=1,lvl=48}),crit(50605,{achID=14307,id=14})}}),n(160721,{coords={{60.5,73.4,1533}},isDaily=1,questID=58222,g={s(112999,180444,{b=1,f=5,lvl=48}),crit(50596,{achID=14307,id=2})}}),n(158